package co.edu.uco.seguridad.pdp.authorization.application.usecase.impl;
import co.edu.uco.seguridad.pdp.authorization.application.primaryport.request.SearchApplicationSecurityUsersRequest; import co.edu.uco.seguridad.pdp.authorization.application.rule.validator.PrincipalMustBeApplicationAdministratorValidator; import co.edu.uco.seguridad.pdp.authorization.application.usecase.SearchApplicationSecurityUsersUseCase; import co.edu.uco.seguridad.pdp.commons.model.ResultPage; import co.edu.uco.seguridad.pdp.identity.application.primaryport.request.SearchUsersPageRequest; import co.edu.uco.seguridad.pdp.identity.application.primaryport.response.UserResponse; import co.edu.uco.seguridad.pdp.identity.application.usecase.SearchUsersPageUseCase; import reactor.core.publisher.Mono;
public final class SearchApplicationSecurityUsersUseCaseImpl implements SearchApplicationSecurityUsersUseCase {private final PrincipalMustBeApplicationAdministratorValidator gate;private final SearchUsersPageUseCase users;public SearchApplicationSecurityUsersUseCaseImpl(PrincipalMustBeApplicationAdministratorValidator gate,SearchUsersPageUseCase users){this.gate=gate;this.users=users;}public Mono<ResultPage<UserResponse>> execute(SearchApplicationSecurityUsersRequest i){return gate.execute(i.administration()).then(Mono.defer(()->users.execute(new SearchUsersPageRequest(i.administration().tenantId(),i.query(),i.window()))));}}
